package com.jiugeng.erp.forwarder;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.jiugeng.erp.iam.*;
import java.math.*;import java.time.*;import java.util.*;
import org.springframework.stereotype.Service;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
@Service @Transactional
class ForwarderDocuments {
 record Input(String documentNo,String carrier,String status,Map<String,String> fields,List<Map<String,String>> items,Long version){}
 record Document(String id,String documentNo,String carrier,String templateVersion,String status,Map<String,String> fields,List<Map<String,String>> items,long version,String updatedAt){}
 record Summary(String id,String documentNo,String carrier,String status,String waybill,String warehouse,int itemCount,int cartons,String amount,long version,String updatedAt){}
 record Page(List<Summary> items,long totalCount){}
 static final Set<String> HEADERS=Set.of("waybill","reference","warehouse","country","channel","customsType","insured","insurance","battery","magnet","consignee","company","phone","city","region","postalCode","address","address2","shipper","shipperCompany","shipperAddress","shipperCity","shipperRegion","shipperPostalCode","shipperPhone","shipperVat","extraService","consigneeVat","consigneeEori","notes","importer","importerCompany","importerPhone","importerPostalCode","importerCountry","importerRegion","importerCity","importerTax","importerAddress");
 static final Set<String> ITEMS=Set.of("sku","variantId","fba","reference","boxStart","boxCount","boxCode","name","nameEn","hsCode","price","perBox","brand","brandType","model","material","usage","netWeight","grossWeight","length","width","height","image");
 static final Set<String> NUMBERS=Set.of("boxStart","boxCount","price","perBox","netWeight","grossWeight","length","width","height");
 private final JdbcClient jdbc;private final ObjectMapper json;private final AuditTrail audit;
 ForwarderDocuments(JdbcClient jdbc,ObjectMapper json,AuditTrail audit){this.jdbc=jdbc;this.json=json;this.audit=audit;}
 static String text(String s){return s==null?"":s.trim();}static void require(boolean ok,String m){if(!ok)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}
 static BigDecimal number(Map<String,String> m,String k){return text(m.get(k)).isEmpty()?BigDecimal.ZERO:new BigDecimal(m.get(k));}
 static Map<String,String> clean(Map<String,String> in,Set<String> keys){require(in!=null,"缺少单据资料");var out=new LinkedHashMap<String,String>();for(String k:keys){String v=text(in.get(k));require(v.length()<=(k.equals("image")?700000:2000),"字段过长："+k);require(v.chars().noneMatch(c->Character.isISOControl(c)&&c!='\n'&&c!='\r'),"字段含无效字符");out.put(k,v);}return out;}
 Input validate(Input in){require(in!=null,"缺少单据");require(Set.of("KAIQI","HUAMAO").contains(text(in.carrier())),"请选择支持的货代");require(Set.of("DRAFT","READY").contains(text(in.status())),"单据状态无效");var f=clean(in.fields(),HEADERS);require(f.get("country").equals("US"),"当前模板仅用于美国");var rows=new ArrayList<Map<String,String>>();require(in.items()!=null&&in.items().size()<=100,"每票最多100项装箱明细");int bytes=0;long expanded=0;
  for(var item:in.items()){var r=clean(item,ITEMS);for(String k:NUMBERS)if(!r.get(k).isBlank())try{var n=number(r,k);require(n.signum()>=0&&n.scale()<=4&&n.compareTo(new BigDecimal("999999"))<=0,"数量、重量、箱规和单价须为非负数且最多4位小数");if(Set.of("boxStart","boxCount","perBox").contains(k))require(n.stripTrailingZeros().scale()<=0,"箱序号、箱数和单箱数量须为整数");}catch(NumberFormatException e){require(false,"数字格式不正确："+k);}
   if(!r.get("netWeight").isBlank()&&!r.get("grossWeight").isBlank())require(number(r,"netWeight").compareTo(number(r,"grossWeight"))<=0,"净重不能大于毛重");if(!r.get("hsCode").isBlank())require(r.get("hsCode").matches("[0-9]{6,10}"),"HS编码须为6至10位数字");
   if(!r.get("image").isBlank()){byte[] image=image(r.get("image"));bytes+=image.length;require(bytes<=12_000_000,"本票图片总大小不能超过12MB");}expanded+=number(r,"boxCount").longValue();require(expanded<=2000,"每票展开后最多2000行箱内商品");rows.add(r);
  }
  if(!f.get("insurance").isBlank())try{require(new BigDecimal(f.get("insurance")).signum()>=0&&new BigDecimal(f.get("insurance")).scale()<=2,"投保金额须为非负数，最多2位小数");}catch(NumberFormatException e){require(false,"投保金额格式错误");}
  boxes(rows);String no=text(in.documentNo());if(no.isBlank())no="FD"+LocalDate.now().toString().replace("-","")+"-"+UUID.randomUUID().toString().substring(0,8).toUpperCase();require(no.length()<=128,"单据编号过长");var v=new Input(no,in.carrier(),in.status(),f,rows,in.version());if(v.status().equals("READY"))complete(v);return v;
 }
 static byte[] image(String uri){require(uri.startsWith("data:image/png;base64,"),"图片须为PNG格式，请重新上传");try{byte[] bytes=Base64.getDecoder().decode(uri.substring(22));require(bytes.length<=500000&&bytes.length>24,"图片大小不正确");try(var input=javax.imageio.ImageIO.createImageInputStream(new java.io.ByteArrayInputStream(bytes))){var readers=javax.imageio.ImageIO.getImageReaders(input);require(readers.hasNext(),"图片无法识别");var reader=readers.next();try{reader.setInput(input);require(reader.getFormatName().equalsIgnoreCase("png")&&reader.getWidth(0)<=1000&&reader.getHeight(0)<=1000,"图片尺寸或格式不正确");}finally{reader.dispose();}}return bytes;}catch(java.io.IOException|IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"图片内容无效");}}
 static int boxes(List<Map<String,String>> items){var boxes=new HashMap<Integer,String>();for(var r:items){int start=number(r,"boxStart").intValue(),count=number(r,"boxCount").intValue();require(count<=2000,"箱数最多2000");String signature=String.join("|",List.of("boxStart","boxCount","fba","boxCode","grossWeight","netWeight","length","width","height").stream().map(k->text(r.get(k))).toList());for(int i=start;i<start+count;i++){var prior=boxes.putIfAbsent(i,signature);require(prior==null||prior.equals(signature),"箱序范围重叠；同箱混装请填写一致的箱序范围、FBA、箱规与重量");}}return boxes.size();}
 static BigDecimal amount(List<Map<String,String>> rows){return rows.stream().map(r->number(r,"price").multiply(number(r,"perBox")).multiply(number(r,"boxCount"))).reduce(BigDecimal.ZERO,BigDecimal::add).setScale(2,RoundingMode.HALF_UP);}
 static List<String> missing(Input in){var errors=new ArrayList<String>();for(String k:List.of("waybill","warehouse","consignee","company","address","city","region","postalCode"))if(text(in.fields().get(k)).isEmpty())errors.add(LABELS.getOrDefault(k,k));if(in.carrier().equals("KAIQI")){for(String k:List.of("channel","customsType","insured","battery","magnet"))if(text(in.fields().get(k)).isEmpty())errors.add(LABELS.get(k));if("是".equals(in.fields().get("insured"))&&number(in.fields(),"insurance").signum()<=0)errors.add("投保金额");}else for(String k:List.of("shipper","shipperCompany","shipperAddress","shipperCity","shipperRegion","shipperPostalCode","shipperPhone"))if(text(in.fields().get(k)).isBlank())errors.add(LABELS.get(k));
  if(in.items().isEmpty())errors.add("至少一项商品");for(int i=0;i<in.items().size();i++){var r=in.items().get(i);for(String k:List.of("fba","name","nameEn","hsCode","material","usage","image"))if(text(r.get(k)).isBlank())errors.add("商品"+(i+1)+"："+LABELS.get(k));for(String k:List.of("boxStart","boxCount","perBox","price","grossWeight","length","width","height"))if(number(r,k).signum()<=0)errors.add("商品"+(i+1)+"："+LABELS.get(k)+"须大于0");}return errors;
 }
 static final Map<String,String> LABELS=Map.ofEntries(Map.entry("waybill","运单号/批次号"),Map.entry("warehouse","仓库代码"),Map.entry("consignee","收件人"),Map.entry("company","收件人公司"),Map.entry("address","收件地址"),Map.entry("city","城市"),Map.entry("region","州"),Map.entry("postalCode","邮编"),Map.entry("channel","收货渠道"),Map.entry("customsType","报关类型"),Map.entry("insured","是否投保"),Map.entry("battery","是否带电"),Map.entry("magnet","是否带磁"),Map.entry("shipper","发件人"),Map.entry("shipperCompany","发件公司"),Map.entry("shipperAddress","发件地址"),Map.entry("shipperCity","发件城市"),Map.entry("shipperRegion","发件省"),Map.entry("shipperPostalCode","发件邮编"),Map.entry("shipperPhone","发件电话"),Map.entry("fba","FBA编号"),Map.entry("name","中文品名"),Map.entry("nameEn","英文品名"),Map.entry("hsCode","进口HS编码"),Map.entry("material","材质"),Map.entry("usage","用途"),Map.entry("image","产品图片"),Map.entry("boxStart","起始箱序"),Map.entry("boxCount","箱数"),Map.entry("perBox","单箱数量"),Map.entry("price","单价USD"),Map.entry("grossWeight","单箱实际毛重"),Map.entry("length","箱长"),Map.entry("width","箱宽"),Map.entry("height","箱高"));
 static void complete(Input in){var m=missing(in);require(m.isEmpty(),"请完善后导出："+String.join("、",m));}
 Document get(String id){return jdbc.sql("SELECT * FROM forwarder_document WHERE id=:id AND deleted_at IS NULL").param("id",id).query((r,n)->{try{var v=json.readValue(r.getString("payload"),Input.class);return new Document(id,r.getString("document_no"),r.getString("carrier"),r.getString("template_version"),r.getString("status"),v.fields(),v.items(),r.getLong("version"),r.getTimestamp("updated_at").toInstant().toString());}catch(Exception e){throw new IllegalStateException(e);}}).optional().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"货代单据不存在"));}
 Page list(String q,String carrier,int page,int size){require(page>=0&&page<=100000&&size>=1&&size<=100&&q.length()<=128,"查询参数无效");require(Set.of("","KAIQI","HUAMAO").contains(carrier),"货代无效");String where=" WHERE deleted_at IS NULL AND (:carrier='' OR carrier=:carrier) AND LOWER(document_no) LIKE :q ESCAPE '!'";String term="%"+q.toLowerCase().replace("!","!!").replace("%","!%").replace("_","!_")+"%";long total=jdbc.sql("SELECT COUNT(*) FROM forwarder_document"+where).param("carrier",carrier).param("q",term).query(Long.class).single();var rows=jdbc.sql("SELECT id,document_no,carrier,status,waybill,warehouse,item_count,cartons,amount,version,updated_at FROM forwarder_document"+where+" ORDER BY updated_at DESC,id DESC LIMIT :size OFFSET :offset").param("carrier",carrier).param("q",term).param("size",size).param("offset",page*size).query((r,n)->new Summary(r.getString("id"),r.getString("document_no"),r.getString("carrier"),r.getString("status"),r.getString("waybill"),r.getString("warehouse"),r.getInt("item_count"),r.getInt("cartons"),r.getBigDecimal("amount").toPlainString(),r.getLong("version"),r.getTimestamp("updated_at").toInstant().toString())).list();return new Page(rows,total);}

 Document save(String id,Input input,AuthenticatedActor actor){var in=validate(input);try{String payload=json.writeValueAsString(in);if(id==null){id=UUID.randomUUID().toString();jdbc.sql("INSERT INTO forwarder_document(id,document_no,carrier,template_version,status,payload,waybill,warehouse,item_count,cartons,amount) VALUES(:id,:no,:carrier,'v1',:status,:payload,:waybill,:warehouse,:count,:cartons,:amount)").param("id",id).param("no",in.documentNo()).param("carrier",in.carrier()).param("status",in.status()).param("payload",payload).param("waybill",in.fields().get("waybill")).param("warehouse",in.fields().get("warehouse")).param("count",in.items().size()).param("cartons",boxes(in.items())).param("amount",amount(in.items())).update();}else{var before=get(id);require(before.carrier().equals(in.carrier()),"已保存单据不能切换货代，请新建单据");int n=jdbc.sql("UPDATE forwarder_document SET document_no=:no,status=:status,payload=:payload,waybill=:waybill,warehouse=:warehouse,item_count=:count,cartons=:cartons,amount=:amount,version=version+1,updated_at=CURRENT_TIMESTAMP WHERE id=:id AND version=:v AND deleted_at IS NULL").param("id",id).param("no",in.documentNo()).param("status",in.status()).param("payload",payload).param("waybill",in.fields().get("waybill")).param("warehouse",in.fields().get("warehouse")).param("count",in.items().size()).param("cartons",boxes(in.items())).param("amount",amount(in.items())).param("v",in.version()).update();if(n!=1)throw new ResponseStatusException(HttpStatus.CONFLICT,"单据已变化，请重新打开");}var d=get(id);record(actor,"FORWARDER_DOCUMENT_SAVE",d);return d;}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw new IllegalStateException(e);}}
 void delete(String id,long version,AuthenticatedActor actor){var d=get(id);int n=jdbc.sql("UPDATE forwarder_document SET deleted_at=CURRENT_TIMESTAMP,deletion_key=id,version=version+1 WHERE id=:id AND version=:v AND deleted_at IS NULL").param("id",id).param("v",version).update();if(n!=1)throw new ResponseStatusException(HttpStatus.CONFLICT,"单据已变化，请刷新");record(actor,"FORWARDER_DOCUMENT_DELETE",d);}
 void record(AuthenticatedActor actor,String action,Document d){audit.record(new AuditTrail.BusinessOperation(actor.userId(),actor.loginName(),actor.displayName(),action,"FORWARDER_DOCUMENT",d.id(),true,null,Map.of("carrier",d.carrier(),"version",d.version()),"货代模板单据"));}
}
